{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    children_map = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children_map.setdefault(pid, []).append(n['id'])
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_ids = set()
    removed_order = []
    for node in sorted_nodes:
        nid = node['id']
        if not node['removable'] or node['symbol'] in required_symbols:
            continue
        children = children_map.get(nid, [])
        if any(cid not in removed_ids for cid in children):
            continue
        removed_ids.add(nid)
        removed_order.append(nid)
    all_ids = {n['id'] for n in nodes}
    retained_ids = sorted(all_ids - removed_ids)
    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_ids
    }"}
